// Controlled unit records for typed evidence validation; never actual model or hosted proof.
import {writeFile,readFile} from 'node:fs/promises';import {join} from 'node:path';import {randomUUID} from 'node:crypto';
import {sdkEvidenceFixture} from './sdk-evidence';import {writeEvidence,evidenceDigest} from '../../../scripts/pilot-evidence';
import {hostedLearningIndependentReviewSchema} from '../../../scripts/pilot-hosted-learning-journey';import {learningCaseReviewSchema} from '../../../lib/contracts/learning';
const sha=(value:unknown)=>evidenceDigest(JSON.stringify(value));
export async function addPartnerEvidenceFixture(f:Awaited<ReturnType<typeof sdkEvidenceFixture>>){
 const linked=(f.capture as unknown as {linkedJourneys?:{source:{profileRevisionId:string};knowledge:{contributionId:string;publicationId:string};plan:{revisionId:string;engagementId:string;baselineId:string}}[]}).linkedJourneys?.[0];
 const now=Date.parse(f.capture.completedAt)+2000,at=(offset:number)=>new Date(now+offset).toISOString(),scope=f.scope,evaluationId=randomUUID(),budgetId=randomUUID(),assignmentId=randomUUID(),attemptId=randomUUID(),publicationId=linked?.knowledge.publicationId??randomUUID(),contributionId=linked?.knowledge.contributionId??randomUUID(),sourceRevisionId=linked?.source.profileRevisionId??randomUUID(),reviewId=randomUUID(),planRevisionId=linked?.plan.revisionId??randomUUID(),engagementId=linked?.plan.engagementId??randomUUID(),baselineId=linked?.plan.baselineId??randomUUID(),customerId=f.capture.sdkJourneys[0].customerId,arms=[] as {caseId:string;purpose:'evaluation_baseline'|'evaluation_candidate';capture:unknown}[],retired=[] as Record<string,unknown>[];
 for(let index=0;index<16;index++){const caseId='E'+String(Math.floor(index/2)+1).padStart(2,'0'),purpose=index%2?'evaluation_candidate':'evaluation_baseline',id=randomUUID(),native='wrun_controlled_unit_'+index,output={kind:'abstain',text:'Controlled unit artifact only.',citationKeys:[],unknowns:['No actual hosted execution is asserted.']},capture={evaluationId,caseId,bodyAvailable:true,arm:{id,state:'completed',output,outputDigest:sha(output),modelSteps:1,nativeSessionId:native,nativeRequestId:randomUUID()}};
  arms.push({caseId,purpose,capture});retired.push({id,state:'completed',native_session_id:native,eve_session_id:native,cleanup_state:'completed',retired_native_session_id:native});await writeEvidence(f.directory,'learning-'+String(index+1).padStart(2,'0')+'-capture.json',{capture,accounting:{contract:'pilot-hosted-learning-reconciliation-v1',journalDispatchId:randomUUID(),journalBudgetId:budgetId,reservationId:randomUUID(),learningAttemptId:id,actualMicroUsd:1,generation:{id:'controlled-unit-generation-'+index,streamed:true,usage:0.000001,totalCost:0.000001},domainAccountingMatches:true,modelCalls:0,providerReads:1,approvalExtended:false,budgetReopened:false,reconciliationSuccessful:true,originalHoldRetained:false}});
 }
 const manifest={contract:'pilot-hosted-learning-review-manifest-v1',scope,evaluationId,cases:arms},review=hostedLearningIndependentReviewSchema.parse({contract:'pilot-hosted-learning-independent-review-v1',scope,evaluationId,captureManifestDigest:sha(manifest),reviewerReference:'controlled unit reviewer',method:'automated-independent-review',reviewedAt:at(-2000),cases:Array.from({length:8},(_,index)=>{const baseline=(arms[index*2].capture as {arm:{outputDigest:string}}).arm.outputDigest,candidate=(arms[index*2+1].capture as {arm:{outputDigest:string}}).arm.outputDigest;return {caseId:'E'+String(index+1).padStart(2,'0'),baselineCaptureDigest:baseline,candidateCaptureDigest:candidate,baseline:{fidelity:2,applicability:2,unknownHandling:2,usefulness:2},candidate:{fidelity:2,applicability:2,unknownHandling:2,usefulness:2},safetyPassed:true,citationPassed:true,authorityPassed:true,rationale:'Controlled no-benefit unit fixture; not an actual model assessment.'};})});
 await writeEvidence(f.directory,'learning-independent-review-manifest.json',{...manifest,captureManifestDigest:sha(manifest),reviewMethod:'automated-independent-review',actualHumanReviewVerified:false});await writeEvidence(f.directory,'learning-independent-review.json',review);
 for(const [index,row] of review.cases.entries()){const command=learningCaseReviewSchema.parse({...row,contractVersion:'learning-v1',requestId:randomUUID(),expectedVersion:index+1});await writeEvidence(f.directory,'learning-review-'+row.caseId+'-intent.json',{evaluationId,command,reviewDigest:sha(review),method:'automated-independent-review'});await writeEvidence(f.directory,'learning-review-'+row.caseId+'-receipt.json',{requestId:command.requestId,targetId:randomUUID(),version:index+2});}
 const completed={contract:'pilot-hosted-learning-journey-v1',journey:'J014',contributionId,sourceRevisionId,startedAt:at(-3100),completedAt:at(-1500),evaluationId,state:'failed',reviewDigest:sha(review),reviewMethod:'automated-independent-review',reviewedCases:8,actualHumanReviewVerified:false,publicationDenied:true,publicationId,publicationGeneration:1,pairedModelArms:16,originalBudgetId:budgetId,originalAccountingPreserved:true,retirementVerified:true,automatedObservation:true,actualHumanObservation:false};
 await writeEvidence(f.directory,'learning-completed.json',completed);await writeEvidence(f.directory,'learning-retirement.json',{contract:'pilot-hosted-learning-retirement-v1',scope,evaluationId,rows:retired,retirementVerified:true,modelCalls:0,automaticPaidRetries:0});await writeEvidence(f.directory,'learning-prepared.json',{evaluationId,contributionId,reviewId,baselineGeneration:1});await writeEvidence(f.directory,'learning-partner-boundary.json',{scope,evaluationId,role:'assigned-partner',startedAt:at(-1400),completedAt:at(-1300),internalEvaluationWithheld:true});
 const withdrawalPath=join(f.directory,'current-source-withdrawal.json'),previousWithdrawal=await readFile(withdrawalPath,'utf8').then(value=>JSON.parse(value)).catch(error=>{if(error.code==='ENOENT')return {};throw error;});await writeFile(withdrawalPath,JSON.stringify({...previousWithdrawal,...{runId:f.run.id,workspaceId:scope.workspaceId,environmentMarker:scope.environmentMarker,sourceCommit:scope.sourceCommit,sourceDigest:scope.sourceDigest,catalogDigest:scope.catalogDigest,trainingAssignmentId:assignmentId,trainingAttemptId:attemptId,partnerCreditWithheld:true,completedAt:at(-700)}})+'\n',{mode:0o600});
 await writeEvidence(f.directory,'learning-publication-intent.json',{contributionId,decision:{action:'publish',requestKey:randomUUID(),learningEvaluationId:evaluationId,learningReviewId:reviewId,expectedBaselineGeneration:1}});
 const training={contract:'pilot-hosted-training-chain-v1',customerId,sourceRevisionId,acceptedRevisionId:planRevisionId,engagementId,baselineId,guide:{contract:'pilot-partner-guide-v1',assignmentId,guideId:randomUUID(),revisionId:randomUUID(),normalCommands:4,reviewPreviews:2,providerCalls:0},training:{contract:'pilot-partner-training-v1',assignmentId,attemptId,checkpointId:randomUUID(),normalCommands:3,reviewPreviews:1,providerCalls:0,learningIsNotDeliveryAcceptance:true},roles:{contract:'pilot-hosted-read-checks-v1',cases:['internal-admin','internal-member','assigned-partner'].flatMap(role=>['session-bound','positive-customer-scope','operations-authority','product-gaps-read-boundary','exact-session-revoked'].map(id=>({id,role,state:'pass',status:id==='operations-authority'&&role!=='internal-admin'?403:id==='product-gaps-read-boundary'&&role==='assigned-partner'?404:200}))),passedCases:15,sessionsRevoked:3,providerCalls:0},startedAt:at(-3800),completedAt:at(-3200),partnerExecution:{startedAt:at(-3400),completedAt:at(-3300)},humanFeedbackRecorded:false,skillsCertified:false};
 const capture={...f.capture,...('roleIntervals' in f.capture?{roleIntervals:(f.capture.roleIntervals as {role:string;startedAt:string;completedAt:string}[]).map(row=>({...row,completedAt:at(-300)}))}:{}),completedAt:at(-300),sdkJourneys:f.capture.sdkJourneys.map(row=>({...row,startedAt:at(-1400),completedAt:at(-500)})),linkedJourneys:linked?[linked]:[{customerId,source:{versionId:randomUUID(),profileRevisionId:sourceRevisionId},knowledge:{contributionId,publicationId},plan:{revisionId:planRevisionId,engagementId,baselineId}}],trainingJourneys:[training],learningJourneys:[completed]};await writeFile(join(f.directory,'reads.json'),JSON.stringify(capture)+'\n',{mode:0o600});return {completed,training,review,capture,evaluationId,budgetId};
}
